arguments.command:
python3 -c "
from pptx import Presentation
prs = Presentation('/app/output/final_deck.pptx')
for i, slide in enumerate(prs.slides, 1):
    texts = []
    for shape in slide.shapes:
        if shape.has_text_frame:
            for p in shape.text_frame.paragraphs:
                if p.text.strip():
                    texts.append(p.text.strip()[:80])
        if shape.has_table:
            t = shape.table
            texts.append(f'TABLE {len(t.rows)}x{len(t.columns)}')
        if shape.has_chart:
            texts.append(f'CHART: {shape.chart.chart_type.name}')
    print(f'--- Slide {i} ---')
    for t in texts[:8]:
        print(t)
    print()
"
